const fs = require('fs');
let offset = 0;
try { 
  const data = JSON.parse(fs.readFileSync('/data/telegram_offset.json', 'utf8'));
  offset = data.offset || 0;
} catch(e) {}

const results = [];
const items = $input.all();

for (let item of items) {
  const response = item.json;
  if (response.ok && response.result) {
    for (let update of response.result) {
      if (update.update_id >= offset) {
        offset = update.update_id + 1;
      }
      if (update.callback_query && update.callback_query.data) {
         if (update.callback_query.data.startsWith('APPLY:')) {
            results.push({ json: { update: update } });
         }
      }
    }
  }
}

if (offset > 0) {
  fs.writeFileSync('/data/telegram_offset.json', JSON.stringify({ offset: offset }));
}

return results;
